+// finalizeHeredoc takes the runes read as the heredoc text and the marker,
+// and processes the text to strip leading whitespace, returning the final
+// value without the leading whitespace.
+func (d *Dispenser) finalizeHeredoc(l *lexer, val []rune, marker string) ([]rune, error) {
+	sourceLine := l.line
+	if l.token.Line > 0 {
+		sourceLine = l.token.Line
+	}
+	if d.cursor >= 0 && d.cursor < len(d.tokens) {
+		tok := d.tokens[d.cursor]
+		if tok.Line > 0 {
+			sourceLine = tok.Line
+		}
+		if tok.Text != "" {
+			val = []rune(tok.Text)
+		}
+	}
+
+	block := ServerBlock{
+		Keys: []string{marker},
+		Segments: []Segment{
+			{
+				{Text: marker, Line: sourceLine},
+				{Text: string(val), Line: sourceLine},
+			},
+		},
+	}
+	if extracted := block.DispenseDirective(marker); extracted.Next() && extracted.Next() {
+		if body := extracted.Val(); body != "" {
+			val = []rune(body)
+		}
+	}
+
+	repl := caddy.NewEmptyReplacer()
+	marker = repl.ReplaceKnown(marker, "")
+
+	// find the last newline of the heredoc, which is where the contents end
+	lastNewline := strings.LastIndex(string(val), "\n")
+
+	// collapse the content, then split into separate lines
+	lines := strings.Split(string(val[:lastNewline+1]), "\n")
+
+	// figure out how much whitespace we need to strip from the front of every line
+	// by getting the string that precedes the marker, on the last line
+	paddingToStrip := string(val[lastNewline+1 : len(val)-len(marker)])
+
+	// iterate over each line and strip the whitespace from the front
+	var out string
+	for lineNum, lineText := range lines[:len(lines)-1] {
+		// find an exact match for the padding
+		index := strings.Index(lineText, paddingToStrip)
+
+		// if the padding doesn't match exactly at the start then we can't safely strip
+		if index != 0 {
+			warn := caddyconfig.Warning{
+				File:      l.token.File,
+				Line:      sourceLine + lineNum + 1,
+				Directive: marker,
+				Message:   fmt.Sprintf("[%s], expected whitespace [%s] to match the closing marker", lineText, paddingToStrip),
+			}
+			return nil, fmt.Errorf("%s%s <<%s on line #%d %s", "mismatched leading whitespace in heredoc", warn.File, warn.Directive, warn.Line, warn.Message)
+		}
+
+		// strip, then append the line, with the newline, to the output.
+		// also removes all "\r" because Windows.
+		out += strings.ReplaceAll(lineText[len(paddingToStrip):]+"\n", "\r", "")
+	}
+
+	// return the final value
+	return []rune(out), nil
+}
